// Package tenantevents provides a Kafka consumer module for tenant lifecycle events.
// It handles tenant migrations on create/update and deferred cleanup on delete.
package fxconfig

import (
	commons_consumer "github.com/Sokol111/ecommerce-commons/pkg/kafka/consumer"
	fx_consumer "github.com/Sokol111/ecommerce-commons/pkg/kafka/consumer/fxconfig"
	"github.com/Sokol111/ecommerce-tenant-service-api/pkg/consumer"
	"go.uber.org/fx"
	"go.uber.org/zap"
)

const tenantEventsConsumer = "tenant-events"

// NewKafkaConsumerModule registers a Kafka consumer for tenant events that runs
// database migrations when tenants are created/updated and schedules deferred cleanup on delete.
//
// Requires tenant.NewModule() to be registered in the fx container for Registry and MigrationRunner.
// To add service-specific cleanup, register additional tenant.Cleaner implementations
// in the "tenant_cleaners" fx group:
//
//	fx.Provide(fx.Annotate(s3.NewImageTenantCleaner,
//	    fx.ResultTags(`group:"tenant_cleaners"`),
//	))
func NewKafkaConsumerModule() fx.Option {
	return fx.Options(
		fx.Provide(consumer.NewTenantEventHandler),
		fx_consumer.RegisterHandlerAndConsumer(tenantEventsConsumer, newTenantRouter),
	)
}

func newTenantRouter(h *consumer.TenantEventHandler, log *zap.Logger) commons_consumer.Handler {
	r := commons_consumer.NewRouter(log)
	commons_consumer.Register(r, h.HandleTenantUpdated)
	commons_consumer.Register(r, h.HandleTenantDeleted)
	return r
}

package fxconfig

import (
	"github.com/Sokol111/ecommerce-commons/pkg/kafka/consumer"
	fx_consumer "github.com/Sokol111/ecommerce-commons/pkg/kafka/consumer/fxconfig"
	"github.com/Sokol111/ecommerce-image-service/internal/infrastructure/inbound/kafka"
	"go.uber.org/fx"
	"go.uber.org/zap"
)

func NewKafkaModule() fx.Option {
	return fx.Options(
		fx.Provide(kafka.NewProductHandler),
		fx_consumer.RegisterHandlerAndConsumer("catalog-events", newProductRouter),
	)
}

func newProductRouter(h *kafka.ProductHandler, log *zap.Logger) consumer.Handler {
	r := consumer.NewRouter(log)
	consumer.Register(r, h.HandleProductUpdated)
	consumer.Register(r, h.HandleProductDeleted)
	return r
}

package fxconfig

import (
	fx_connect "github.com/Sokol111/ecommerce-catalog-service/internal/infrastructure/inbound/connect/fxconfig"
	fx_kafka "github.com/Sokol111/ecommerce-catalog-service/internal/infrastructure/outbound/kafka/fxconfig"
	fx_mongo "github.com/Sokol111/ecommerce-catalog-service/internal/infrastructure/outbound/mongo/fxconfig"
	fx_tenant_api "github.com/Sokol111/ecommerce-tenant-service-api/pkg/fxconfig"
	"go.uber.org/fx"
)

func NewInfrastructureModule() fx.Option {
	return fx.Options(
		fx_tenant_api.NewKafkaConsumerModule(),
		fx_tenant_api.NewTenantSlugsProviderModule(),
		fx_tenant_api.NewGrpcClientsModule(),
		fx_mongo.NewMongoModule(),
		fx_kafka.NewKafkaModule(),
		fx_connect.NewConnectModule(),
	)
}

package fxconfig

import (
	fx_connect "github.com/Sokol111/ecommerce-image-service/internal/infrastructure/inbound/connect/fxconfig"
	fx_inbound_kafka "github.com/Sokol111/ecommerce-image-service/internal/infrastructure/inbound/kafka/fxconfig"
	fx_imgproxy "github.com/Sokol111/ecommerce-image-service/internal/infrastructure/outbound/imgproxy/fxconfig"
	fx_outbound_kafka "github.com/Sokol111/ecommerce-image-service/internal/infrastructure/outbound/kafka/fxconfig"
	fx_mongo "github.com/Sokol111/ecommerce-image-service/internal/infrastructure/outbound/mongo/fxconfig"
	fx_s3 "github.com/Sokol111/ecommerce-image-service/internal/infrastructure/outbound/s3/fxconfig"
	fx_token "github.com/Sokol111/ecommerce-image-service/internal/infrastructure/outbound/token/fxconfig"
	fx_tenant_api "github.com/Sokol111/ecommerce-tenant-service-api/pkg/fxconfig"
	"go.uber.org/fx"
)

func NewInfrastructureModule() fx.Option {
	return fx.Options(
		NewTenantModule(),
		NewAdaptersModule(),
	)
}

func NewAdaptersModule() fx.Option {
	return fx.Options(
		fx_mongo.NewMongoModule(),
		fx_imgproxy.NewImgProxyModule(),
		fx_s3.NewS3Module(),
		fx_inbound_kafka.NewKafkaModule(),
		fx_outbound_kafka.NewKafkaModule(),
		fx_token.NewTokenModule(),
		fx_connect.NewConnectModule(),
	)
}

func NewTenantModule() fx.Option {
	return fx.Options(
		fx_tenant_api.NewKafkaConsumerModule(),
		fx_tenant_api.NewTenantSlugsProviderModule(),
		fx_tenant_api.NewGrpcClientsModule(),
	)
}

